import { Link } from "react-router-dom";

import "./Footer.css";

function Footer() {
  return (
    <div>
      <Link to="https://www.instagram.com">
        <img
          src="https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Instagram_logo_2022.svg/1200px-Instagram_logo_2022.svg.png"
          alt="instagram"
        />
      </Link>
    </div>
  );
}

